// The shape group must NOT suppress: it is the one place several candidates
// legitimately survive together.
func TestShapePrototypesAreNotExclusive(t *testing.T) {
	for _, p := range shapePrototypes() {
		if p.Exclusive {
			t.Errorf("shape prototype %q is Exclusive; the length fallback must not suppress", p.Display)
		}
		if p.Tier != hashid.TierShape {
			t.Errorf("shape prototype %q has tier %v, want TierShape", p.Display, p.Tier)
		}
	}
}

// LM is the motivating case for negative evidence: LM digests are upper-case,
// so a lower-case 32-hex input is evidence AGAINST LM, not neutral.
func TestLMIsDemotedOnLowercaseInput(t *testing.T) {
	cs := identifyCandidates("5f4dcc3b5aa765d61d8327deb882cf99")
	for _, c := range cs {
		if c.Type != "lm" {
			continue
		}
		if c.Confidence != hashid.Unlikely {
			t.Fatalf("lm confidence = %v, want unlikely", c.Confidence)
		}
		if c.Reason == "" {
			t.Fatal("lm was demoted without a stated reason")
		}
		return
	}
	t.Fatal("lm was not among the candidates at all")
}

// TestPrototypeTableIntegrity is the mechanical check the rejected embedded
// JSON/TOML approach could not provide: it fails the build if any of the
// 225 prototypes has a malformed field. See task-11-brief.md.
func TestPrototypeTableIntegrity(t *testing.T) {
	table := prototypeTable()
	if len(table) < 150 {
		t.Fatalf("table has %d prototypes; the cascade had ~185 branches — entries are missing", len(table))
	}

	seenDisplay := make(map[string]int)
	for i := range table {
		p := &table[i]
		label := p.Display
		if label == "" {
			t.Errorf("prototype %d has an empty Display", i)
			label = "<unnamed>"
		}
		if p.Match == nil && p.Compute == nil {
			t.Errorf("prototype %q has neither Match nor Compute", label)
		}
		if p.Match != nil && p.Compute != nil {
			t.Errorf("prototype %q sets both Match and Compute; it must set exactly one", label)
		}
		if strings.TrimSpace(p.Rationale) == "" {
			t.Errorf("prototype %q has an empty Rationale; an unexplained prevalence is an unfalsifiable claim", label)
		}
		if p.Prevalence > 100 {
			t.Errorf("prototype %q has Prevalence %d, want 0-100", label, p.Prevalence)
		}
		// A Compute prototype supplies its names at match time, so an empty
		// Types is correct there and only there.
		if len(p.Types) == 0 && p.Compute == nil {
			t.Errorf("prototype %q declares no Types and has no Compute", label)
		}
		if len(p.Types) > 0 && p.Compute != nil {
			t.Errorf("prototype %q sets both Types and Compute; it must set exactly one", label)
		}
		for _, typ := range p.Types {
			if typ != canonicalHashType(typ) {
				t.Errorf("prototype %q declares %q, which is an alias; use the canonical name %q",
					label, typ, canonicalHashType(typ))
			}
			if _, ok := universalHashRegistry.formats[typ]; !ok {
				t.Errorf("prototype %q declares unknown type %q", label, typ)
			}
		}
		if prev, dup := seenDisplay[p.Display]; dup {
			t.Errorf("Display %q is used by prototypes %d and %d; names must be unique so output is unambiguous",
				p.Display, prev, i)
		}
		seenDisplay[p.Display] = i
	}
}

// TestEmittedTypesAreRegistered closes the gap TestPrototypeTableIntegrity
// cannot: six prototypes (the BLAKE2 family; WPA PMKID/EAPOL; Rails RESTful
// auth; Cisco PIX/ASA + Oracle H; the salted-digest construction; Bitcoin/
// Litecoin address recovery) compute their Types at match time via Compute
// rather than declaring them, so the static loop above never runs for them —
// a typo inside one of those closures would pass silently.
//
// Go cannot inspect a closure's returned strings statically, so this check
// is dynamic instead: it runs the frozen golden corpus through the table and
// validates every type the table actually emitted.
//
// Residual limit: this only covers types the corpus elicits. A Compute
// branch no corpus input reaches is still unverified — this is strictly
// better than the zero coverage those six entries had before, not exhaustive
// coverage of every path through them.
func TestEmittedTypesAreRegistered(t *testing.T) {
	seen := make(map[string]struct{})
	for _, input := range goldenDetectInputs() {
		got, _ := detectTypesFromTable(input)
		for _, typ := range got {
			if typ != canonicalHashType(typ) {
				t.Errorf("input %q: table emitted %q, which is an alias; want canonical name %q",
					input, typ, canonicalHashType(typ))
			}
			if _, ok := universalHashRegistry.formats[typ]; !ok {
				t.Errorf("input %q: table emitted unknown type %q", input, typ)
			}
			seen[typ] = struct{}{}
		}
	}
	t.Logf("validated %d distinct emitted types across %d corpus inputs", len(seen), len(goldenDetectInputs()))
}
